import json
from collections import Counter
root="/tmp/qwen-issue-710-arw-source/.tmp/codex/01a110fc-4123-7b70-af69-fae5219fa9dc/_reviewer-cap/runs/f45d6db0-cc5a-41c7-8170-be85d7201b9c/ca/2"
p=root+"/.tmp/codex/01a110fc-4123-7b70-af69-fae5219fa9dc/_commit-audit-capability/review.jsonl"
req=json.load(open(root+"/.tmp/codex/01a110fc-4123-7b70-af69-fae5219fa9dc/_commit-audit-capability/request.json"))
lines=open(p,encoding="utf-8").read().splitlines()
recs=[];bad=[]
for i,l in enumerate(lines,1):
    if not l.strip(): bad.append((i,"empty line")); continue
    try: r=json.loads(l)
    except Exception as e: bad.append((i,str(e))); continue
    keys=set(r)
    if keys not in ({"source","requirement","result","evidence"},{"source","requirement","result","evidence","finding"}):
        bad.append((i,"keys "+",".join(sorted(keys))))
    if r.get("result") not in ("satisfied","gap","uncertain"): bad.append((i,"result"))
    if r.get("result") in ("gap","uncertain") and not r.get("finding"): bad.append((i,"missing finding"))
    if r.get("result")=="satisfied" and "finding" in r: bad.append((i,"finding on satisfied"))
    src=r.get("source")
    if not isinstance(src,dict) or not isinstance(src.get("filePath"),str) or not isinstance(src.get("line"),int) or src.get("line")<1: bad.append((i,"source"))
    ev=r.get("evidence")
    if not isinstance(ev,list) or not ev: bad.append((i,"evidence empty"))
    else:
        for e in ev:
            if set(e)=={"filePath","lines"}:
                if not isinstance(e["filePath"],str): bad.append((i,"evidence filePath"))
                for x in e["lines"]:
                    if isinstance(x,int) and x>0: continue
                    if isinstance(x,list) and len(x)==2 and all(isinstance(y,int) and y>0 for y in x): continue
                    bad.append((i,"lines item "+repr(x)))
            elif set(e)=={"command","exitCode"}:
                if not isinstance(e.get("command"),str) or not e["command"]: bad.append((i,"command"))
                if not isinstance(e.get("exitCode"),int): bad.append((i,"exitCode"))
            else: bad.append((i,"evidence shape "+repr(sorted(e))))
    recs.append(r)
print("total lines",len(lines))
print("bad",bad)
print(Counter(r["result"] for r in recs))
print(sorted(set(r["source"]["filePath"] for r in recs)))
print("keys of request:",list(req.keys()))
