const fs=require("fs");
const p=".tmp/codex/01a110fc-4123-7b70-af69-fae5219fa9dc/_commit-audit-capability/review.jsonl";
const raw=fs.readFileSync(p,"utf8");
const lines=raw.split("\n").filter(l=>l.trim());
const req=JSON.parse(fs.readFileSync(".tmp/codex/01a110fc-4123-7b70-af69-fae5219fa9dc/_commit-audit-capability/request.json","utf8"));
const want=new Set();
for(const g of req.gate1) for(const r of g.requirements) want.add(r.filePath+"#"+r.line);
const got=new Set();
let bad=0;
for(const l of lines){
  const o=JSON.parse(l);
  got.add(o.source.filePath+"#"+o.source.line);
  if(!o.source||!o.requirement||!o.result||!Array.isArray(o.evidence)) bad++;
  if(o.result==="gap"&&!o.finding) bad++;
  if(o.result==="satisfied"&&o.finding) bad++;
}
console.log("lines",lines.length,"bad",bad,"gate1 missing",[...want].filter(k=>!got.has(k)).length);
console.log("gate2 spec distinct lines",[...got].filter(k=>k.includes("spec.md#")).length);
console.log("gap count",lines.filter(l=>JSON.parse(l).result==="gap").length);
'

