const fs=require("fs");
const p=".tmp/codex/01a110fc-4123-7b70-af69-fae5219fa9dc/_commit-audit-capability/review.jsonl";
const lines=fs.readFileSync(p,"utf8").split("\n");
let bad=0,n=0;const res={};const bySrc={};
for(const line of lines){ if(!line.trim()) continue; n++; let o; try{o=JSON.parse(line);}catch(e){bad++;console.log("PARSE ERR",n,e.message);continue;}
 const keys=Object.keys(o).sort().join(",");
 if(keys!=="evidence,requirement,result,source"&&keys!=="evidence,finding,requirement,result,source"){bad++;console.log("KEYS",n,keys);}
 if(!o.source||typeof o.source.filePath!=="string"||typeof o.source.line!=="number"||o.source.line<1||!Number.isInteger(o.source.line)){bad++;console.log("SRC",n,JSON.stringify(o.source));}
 if(!Array.isArray(o.evidence)||o.evidence.length===0){bad++;console.log("EV",n);}
 for(const e of o.evidence){ if(e.command!==undefined){ if(typeof e.command!=="string"||!e.command||typeof e.exitCode!=="number"){bad++;console.log("CMD EV",n,JSON.stringify(e));} } else { if(typeof e.filePath!=="string"||!Array.isArray(e.lines)||e.lines.length===0){bad++;console.log("FILE EV",n,JSON.stringify(e));} else { for(const l of e.lines){ if(typeof l==="number"){ if(!Number.isInteger(l)||l<1){bad++;console.log("LINE",n,l);} } else if(Array.isArray(l)){ if(l.length!==2||l.some(x=>!Number.isInteger(x)||x<1)||l[0]>l[1]){bad++;console.log("RANGE",n,JSON.stringify(l));} } else bad++,console.log("LINES",n,JSON.stringify(l)); } } }
 res[o.result]=(res[o.result]||0)+1;
 if(o.result==="satisfied"&&o.finding!==undefined){bad++;console.log("FINDING ON SAT",n);}
 if((o.result==="gap"||o.result==="uncertain")&&(!o.finding||typeof o.finding!=="string")){bad++;console.log("MISSING FINDING",n);}
 const k=o.source.filePath+"|"+o.source.line+"|"+o.requirement;
 bySrc[k]=(bySrc[k]||0)+1;
}
console.log("lines",n,"bad",bad,"results",res);
const dup=Object.entries(bySrc).filter(([k,v])=>v>1);
console.log("dups",dup.length,dup.slice(0,5));
const perFile={};
for(const line of lines){ if(!line.trim())continue; const o=JSON.parse(line); perFile[o.source.filePath]=(perFile[o.source.filePath]||0)+1;}
console.log(perFile);
'

