const t = await import("./src/dispatch/telemetry.mjs");
console.log("redactManifestEvent:", JSON.stringify(t.redactManifestEvent({event: "x", auth: {token: "secret", driverName: "Ada"}})));
console.log("auditFieldsPresent ok/missing:", t.auditFieldsPresent({action: "a", actor: "b", timestamp: 1}), t.auditFieldsPresent({action: "a"}));
const q = await import("./src/dispatch/queue.mjs");
const src = [{priority: 1, sequence: 1}];
const frozen = q.freezeDispatchPlan({stops: src});
console.log("freeze stops frozen:", Object.isFrozen(frozen.stops), "copy:", frozen.stops !== src);
console.log("append new list:", q.appendStableStop(src, {priority: 2}) !== src, "src len:", src.length);
const s = await import("./src/dispatch/schedule.mjs");
const w = {startHour: 2, endHour: 4};
const bl = {startHour: 6, endHour: 8};
console.log("windowContains 2,4,5:", s.windowContains(2, w), s.windowContains(4, w), s.windowContains(5, w));
console.log("blackout 6,8,5:", s.isWithinBlackout(6, bl), s.isWithinBlackout(8, bl), s.isWithinBlackout(5, bl));
console.log("nextDispatchTime:", s.nextDispatchTime(new Date("2026-10-07T10:00:00Z"), new Date("2026-10-07T12:00:00Z")).toISOString());
const c = await import("./src/dispatch/capacity.mjs");
console.log("split at limit:", JSON.stringify(c.splitOverweightStops([{weight: 10}, {weight: 11}], 10)));
console.log("zero capacity:", c.resolveVehicleCapacity(0, 10), "remaining:", c.remainingVehicleCapacity(5, 9), "total:", c.totalPackageWeight([{weight: 4}, {weight: 5}]);
NODEEOF

