import json,subprocess
p=".tmp/codex/01a110fc-4123-7b70-af69-fae5219fa9dc/_commit-audit-capability/review.jsonl"
lines=open(p).read().splitlines()
cache={}
bad=[]
gate2=[]
for i,l in enumerate(lines,1):
    d=json.loads(l)
    for ev in d["evidence"]:
        if "command" in ev:
            if not isinstance(ev["command"],str) or not ev["command"] or not isinstance(ev["exitCode"],int): bad.append((i,ev))
            continue
        f=ev["filePath"]
        if f not in cache:
            r=subprocess.run(["git","show",":"+f],capture_output=True,text=True)
            if r.returncode!=0: bad.append((i,"missing staged file",f,r.returncode)); continue
            cache[f]=r.stdout.splitlines()
        ln=ev["lines"]
        spans=ln if isinstance(ln,list) else [ln]
        for s in spans:
            if isinstance(s,list):
                if len(s)!=2 or not all(isinstance(x,int) and x>0 for x in s): bad.append((i,"bad span",f,s)); continue
                a,b=s
                if a>b: bad.append((i,"reversed span",f,s))
                if b>len(cache[f]): bad.append((i,"out of range",f,s,len(cache[f])))
            else:
                if not isinstance(s,int) or s<=0: bad.append((i,"bad line",f,s))
                elif s>len(cache[f]): bad.append((i,"out of range",f,s,len(cache[f]))
        # per-file at most one file evidence object
        fc=[e for e in ev if False]
    files=[e["filePath"] for e in d["evidence"] if "filePath" in e]
    if len(files)!=len(set(files)): bad.append((i,"duplicate file evidence",files))
    if d["source"]["filePath"] in cache:
        pass
print("bad:",bad[:20], len(bad))
# gate2 coverage
spec=cache[".scratch/0001-dispatch-control/spec.md"]
g2=[(json.loads(l)["source"]["line"]) for l in lines if json.loads(l)["source"]["filePath"]==".scratch/0001-dispatch-control/spec.md"]
print("gate2 count",len(g2),"distinct",len(set(g2)),sorted(g2))
PY

