import json,subprocess
p=".tmp/codex/01a110fc-4123-7b70-af69-fae5219fa9dc/_commit-audit-capability/review.jsonl"
lines=open(p).read().splitlines()
cache={}
bad=[]
for i,l in enumerate(lines,1):
    d=json.loads(l)
    for ev in d["evidence"]:
        if "command" in ev:
            if not isinstance(ev["command"],str) or not ev["command"] or not isinstance(ev["exitCode"],int):
                bad.append((i,"bad command evidence",ev))
            continue
        f=ev["filePath"]
        if f not in cache:
            r=subprocess.run(["git","show","+"+f],capture_output=True,text=True)
            if r.returncode!=0:
                bad.append((i,"staged file missing",f,r.returncode))
                cache[f]=[]
            else:
                cache[f]=r.stdout.splitlines()
        ln=ev["lines"]
        spans=ln if isinstance(ln,list) else [ln]
        prev=None
        for s in spans:
            if isinstance(s,list):
                if len(s)!=2 or not all(isinstance(x,int) and x>0 for x in s):
                    bad.append((i,"bad span",f,s)); continue
                a,b=s
                if a>b: bad.append((i,"reversed span",f,s))
                if b>len(cache[f]): bad.append((i,"out of range",f,s,len(cache[f])))
                if prev is not None and a<=prev+1: bad.append((i,"not merged/adjacent",f,prev,s))
                prev=b
            else:
                if not isinstance(s,int) or s<=0: bad.append((i,"bad line",f,s))
                elif s>len(cache[f]): bad.append((i,"out of range",f,s,len(cache[f]))
                if prev is not None and s<=prev+1: bad.append((i,"not merged/adjacent",f,prev,s))
                prev=s
    files=[e["filePath"] for e in d["evidence"] if "filePath" in e]
    if len(files)!=len(set(files)): bad.append((i,"duplicate file evidence",files))
    src=d["source"]
    if src["filePath"] not in cache:
        r=subprocess.run(["git","show","+"+src["filePath"]],capture_output=True,text=True)
        cache[src["filePath"]]=r.stdout.splitlines()
    if src["line"]>len(cache[src["filePath"]]): bad.append((i,"source line out of range",src["filePath"],src["line"],len(cache[src["filePath"]])))
