for b in bad[:40]: print(b)
g2=[json.loads(l) for l in lines if json.loads(l)["source"]["filePath"]==".scratch/0001-dispatch-control/spec.md"]
print("gate2 records:",len(g2),"distinct lines:",len({d["source"]["line"] for d in g2}))
print("gate2 line set:",sorted(d["source"]["line"] for d in g2))
